select c.relname,c.relrowsecurity,has_table_privilege('anon',c.oid,'SELECT') as anon_select,has_table_privilege('authenticated',c.oid,'SELECT') as authenticated_select,has_table_privilege('service_role',c.oid,'SELECT') as service_role_select from pg_class c join pg_namespace n on n.oid=c.relnamespace where (n.nspname='private' and c.relname='lab_rank_shadow_preflight_v1') or (n.nspname='public' and c.relname in ('official_predictions','jra_prediction_jobs'));
